static const char *embedded_macro_tc =
    "; tc.macro - tool change handler for grblHAL.\n"
    ";\n"
    "; Replaces the firmware's built-in M6 flow. Triggered automatically when\n"
    "; /tc.macro is present at the SD card root and the SDcard plugin attaches\n"
    "; (boot or after $FM). With this in place, $341/$342/$343/$345/$346 are\n"
    "; ignored — all tool change behavior is defined here.\n"
    ";\n"
    "; Flow:\n"
    ";   - Spindle/coolant off, lift Z to safe (machine -5).\n"
    ";   - For real swaps (selected_tool != 8): rapid to G30 (foam bin),\n"
    ";     prompt operator, M0 hold for cycle start.\n"
    ";   - For T8 (sentinel = probe already in spindle): skip swap.\n"
    ";   - Rapid to G59.3 origin (over puck).\n"
    ";   - Probe puck: seek down at F500, pull off 2mm, slow re-touch at F25.\n"
    ";     G38.2 auto-routes to the toolsetter input because XY is at G59.3\n"
    ";     within TOOLSETTER_RADIUS (motion_control.c:1018-1019).\n"
    ";   - First call of session (#<_tlo_ref> == 0): store probe machine-Z as\n"
    ";     the reference; no G43.1 applied.\n"
    ";   - Subsequent calls: G43.1 Z[probe_z - tlo_ref] applies dynamic TLO.\n"
    ";   - Park at G30.\n"
    ";\n"
    "; Required state:\n"
    ";   - Machine is homed.\n"
    ";   - G30 is set to the tool-swap position (over foam bin, near max Z).\n"
    ";   - G59.3 is set to the toolsetter approach position (over puck,\n"
    ";     XY centered, Z high enough that the longest tool clears the puck\n"
    ";     during the XY rapid in).\n"
    ";   - #<_tlo_ref> is initialized to 0 at start of session (start_job.macro\n"
    ";     does this).\n"
    ";\n"
    "; Firmware-supplied NGC params:\n"
    ";   #<_current_tool>  - currently mounted tool ID\n"
    ";   #<_selected_tool> - T value from M6 T<n>\n"
    "\n"
    "(PRINT, TC01 ENTER cur=#<_current_tool> sel=#<_selected_tool>)\n"
    "\n"
    "M5\n"
    "M9\n"
    "G53 G0 Z-5\n"
    "\n"
    "o100 IF [#<_selected_tool> NE 8]\n"
    "  ; Safe-Z goto to G30 (Z already lifted to -5 above): traverse XY at the safe\n"
    "  ; height, then move Z. Decomposed by hand because grblHAL runs this macro\n"
    "  ; directly - ioSender's \"safe Z on Go To\" only rewrites gotos it sends itself.\n"
    "  ; #5181/#5182/#5183 = stored G30 machine position (ngc_params: g30_home).\n"
    "  G53 G0 X#5181 Y#5182\n"
    "  G53 G0 Z#5183\n"
    "  (MSG, Swap to T#<_selected_tool>, press cycle start)\n"
    "  M0\n"
    "  G49                ; cancel old tool's TLO before probing the new one\n"
    "o100 ENDIF\n"
    "\n"
    "; --- Rapid to G59.3 (over puck) ---\n"
    "; Safe-Z goto: lift (below), select G59.3, traverse XY at the safe Z, then\n"
    "; descend - rather than the coordinated \"G0 X0 Y0 Z0\", which would move Z while\n"
    "; traversing. Traversing at machine -5 (this macro's safe height) no longer\n"
    "; relies on G59.3's Z being set high enough to clear the puck during the rapid.\n"
    "G53 G0 Z-5\n"
    "G59.3\n"
    "G0 X0 Y0\n"
    "G0 Z0\n"
    "(PRINT, TC02 at G59.3)\n"
    "\n"
    "; --- Select probe input based on the tool in the spindle ---\n"
    "; T8 = 3D mechanical probe. Its stylus is sensitive (sub-mm deflection)\n"
    "; and is NOT designed to bear downward force on the puck. We probe via\n"
    "; the MAIN probe input (pin 15) — the stylus triggers it on first touch,\n"
    "; well before any meaningful pressure on the puck.\n"
    "; Any other tool = rigid cutting tool with no electrical sensing. The\n"
    "; puck's NC switch on the TOOLSETTER input fires when the tool pushes\n"
    "; down on it.\n"
    "; G65 P5 Q<id>: Q0 = Probe_Default (main), Q1 = Probe_Toolsetter (probe.h:40).\n"
    "o150 IF [#<_selected_tool> EQ 8]\n"
    "  G65 P5 Q0\n"
    "  (PRINT, TC02b main probe selected for T8)\n"
    "o150 ELSE\n"
    "  G65 P5 Q1\n"
    "  (PRINT, TC02b toolsetter selected for T#<_selected_tool>)\n"
    "o150 ENDIF\n"
    "\n"
    "G91\n"
    "G38.2 Z-80 F500\n"
    "G0 Z2\n"
    "G38.2 Z-5 F25\n"
    "#<_probe_z> = #5063\n"
    "G0 Z10\n"
    "G90\n"
    "G65 P5 Q0\n"
    "G54\n"
    "(PRINT, TC03 probe_z=#<_probe_z>)\n"
    "\n"
    "o200 IF [#<_tlo_ref> EQ 0]\n"
    "  #<_tlo_ref> = #<_probe_z>\n"
    "  (PRINT, TC04 TLO REF SET ref=#<_tlo_ref>)\n"
    "o200 ELSE\n"
    "  G43.1 Z[#<_probe_z> - #<_tlo_ref>]\n"
    "  (PRINT, TC05 TLO APPLIED tlo=[#<_probe_z> - #<_tlo_ref>])\n"
    "o200 ENDIF\n"
    "\n"
    "; Safe-Z goto to G30 (Z lifted just above): traverse XY at the safe height, then\n"
    "; move Z. See the matching note on the G30 swap move earlier in this macro.\n"
    "G53 G0 Z-5\n"
    "G53 G0 X#5181 Y#5182\n"
    "G53 G0 Z#5183\n"
    "(PRINT, TC06 EXIT at G30)\n"
    "\n";

static const char *embedded_macro_pcorner =
    "; pcorner.macro - generalized corner XYZ probe for grblHAL (any of the 4 stock corners).\n"
    ";\n"
    "; Safe probing philosophy: probe Z down to DISCOVER the\n"
    "; spoilboard and stock-top heights, never rapid to an assumed Z; decompose every reposition\n"
    "; into an explicit safe-Z lift -> traverse -> descend; route axis-at-a-time around the corner.\n"
    ";\n"
    "; Drop at the root of the SD card / littlefs. Args are passed via GLOBALS set before a NO-ARG call (grblHAL's\n"
    "; O-word CALL does not reliably accept multiple bracketed call args), then invoke:\n"
    ";   #<_ls_corner> = <1-4>     1=FL 2=FR 3=BL 4=BR. Sets the probe-direction signs:\n"
    ";                               sx = +1 for LEFT corners (1,3), -1 for RIGHT (2,4)   (probe toward the X face)\n"
    ";                               sy = +1 for FRONT corners (1,2), -1 for BACK (3,4)   (probe toward the Y face)\n"
    ";   #<_ls_refx>   = machine X of the reference, just OUTSIDE this corner's X face (clear air).\n"
    ";   #<_ls_refy>   = machine Y of the reference, just OUTSIDE this corner's Y face.\n"
    ";   #<_ls_rad>    = probe tip radius (mm).\n"
    ";   #<_ls_spacer> = sacrificial spacer/backer thickness (mm) UNDER the stock, same footprint (0 = none).\n"
    ";                   Raises the effective floor to spoilboard+spacer so a thin sheet is probed on the\n"
    ";                   material, not down in the backer. Optional; treated as 0 if the caller never sets it.\n"
    ";   #<_ls_thickness> = estimated stock thickness (mm). The X/Y face probes search at the material's\n"
    ";                   MIDPOINT (top - thickness/2) - safely inside the material for any thickness, rather\n"
    ";                   than a fixed offset below the top (which could miss thin stock or catch a top chamfer\n"
    ";                   on thick stock).\n"
    ";   #<_ls_spoilx>, #<_ls_spoily> = offset (mm) from the reference, along this corner's stock-interior\n"
    ";                   direction, to the spoilboard-probe XY (always 0,0 - AT the reference).\n"
    ";   #<_ls_topx>, #<_ls_topy>     = offset (mm) from the reference, into the stock, to the stock-top probe\n"
    ";                   XY. Derived from the probing 3D probe's body diameter (StartJobView.BuildProgram) -\n"
    ";                   not stored per fixture. Also reused as the edge probes' anchor (see below) - no separate\n"
    ";                   edge offset is needed since the top-probe XY is already verified to be over solid stock.\n"
    ";   #<_ls_spoilz> = machine Z of the fixture instance's saved position - the spoilboard probe starts its\n"
    ";                   descent from here (replaces the old dependency on the firmware's single-slot G28 Z).\n"
    ";   #<_ls_searchf>= fast search feed (mm/min), from the probe definition (Probe/Search feed).\n"
    ";   #<_ls_latchf> = slow latch / re-probe feed (mm/min), from the probe definition (Latch feed).\n"
    ";   #<_ls_startz> = >= 9000  -> DISCOVER (first corner): also probe the spoilboard at the reference\n"
    ";                            (clear air below), publishing #<_start_z> as the DISCOVER/REUSE flag.\n"
    ";                            (Use for the FIRST corner only - its reference must clear the probe\n"
    ";                             body, i.e. the fixture instance set roughly half a body diameter to a\n"
    ";                             full body diameter outside the corner - see FixtureEditDialog's schematic.)\n"
    ";                 < 9000  -> REUSE: skip the spoilboard probe. EVERY corner (DISCOVER or REUSE)\n"
    ";                            still probes its OWN stock top, so each reports its own Z (flatness).\n"
    ";   #<_ls_mode>   = 0 = 3D probe (default) - the spoilboard-anchored DISCOVER/REUSE behavior above,\n"
    ";                       unchanged.\n"
    ";                   1 = touch plate - probes by electrical continuity, so it never falsely triggers on\n"
    ";                       non-conductive spoilboard: the separate spoilboard probe is skipped entirely and\n"
    ";                       the DISCOVER corner instead anchors its safety floor to its OWN measured stock-top\n"
    ";                       Z (see the block right after that probe, below). REUSE corners are unaffected -\n"
    ";                       they already just read the shared #<_bottom> global, whichever mode set it.\n"
    ";   #<_ls_plateoffset> = Z (mm) subtracted from the probed top before it is reported as this corner's Z.\n"
    ";                       0 for the 3D probe, and for a touch plate run directly against conductive stock\n"
    ";                       (no plate, no offset). A separate metal touch plate against non-conductive stock\n"
    ";                       sets this to the plate's own known thickness (ProbeDefinition.PlateThickness).\n"
    ";   #<_ls_maxz>   = OPTIONAL machine Z of a known-safe travel height, already trusted by the caller (e.g.\n"
    ";                       the vise's own centre-of-stock probe, run before any corner calls). When > 0, this\n"
    ";                       replaces BOTH the REUSE-corner full retract to machine Z0 (o40 below - normally\n"
    ";                       needed so the tool clears clamp/fence hardware between corners, which the vise has\n"
    ";                       none of) and the pre-top-probe descent estimate (o41's #<_bottom>+30) with this\n"
    ";                       single known height - the tool never travels above it. 0/unset = old behavior\n"
    ";                       (Corner Fence, no prior stock-top knowledge - safe but more conservative).\n"
    ";\n"
    "; Outputs (GLOBAL named params, survive the SUB):\n"
    ";   #<_corner_x> #<_corner_y>   radius-compensated corner XY (machine coords)\n"
    ";   #<_corner_z>                THIS corner's stock-top Z (machine), less #<_ls_plateoffset> - varies\n"
    ";                                per corner = flatness\n"
    ";   #<_start_z>                 published by the DISCOVER call as the REUSE flag for later corners\n"
    ";\n"
    "; Preconditions: homed; probe on the main probe input ($6 polarity correct); stock >= 3 mm AND <= ~25 mm (1 in)\n"
    ";   thick - the stock-top probe now starts just above 1 in for speed, so taller stock would be missed;\n"
    ";   Z probes seek to -140 (keep within $132). The DISCOVER reference must have clear air below it\n"
    ";   to the spoilboard (no fence/clamp) and be >= body-radius outside the faces.\n"
    "\n"
    "O<pcorner> SUB\n"
    "  #<rad>    = #1                 ; tip radius = the single CALL arg; rest via globals\n"
    "  #<corner> = #<_ls_corner>\n"
    "  #<rx>     = #<_ls_refx>\n"
    "  #<ry>     = #<_ls_refy>\n"
    "  #<sz_in>  = #<_ls_startz>\n"
    "  #<mode>   = #<_ls_mode>        ; 0 = 3D probe, 1 = touch plate (see file header)\n"
    "  #<maxz>   = #<_ls_maxz>        ; known-safe travel height (machine Z), 0/unset = no prior stock-top knowledge (see file header)\n"
    "\n"
    "  ; Clear G54 so the absolute Z probes below run in machine coordinates. Without this a stale G54 Z\n"
    "  ; offset makes \"G38.2 Z-140\" exceed travel (soft-limit alarm).\n"
    "  ; Load Stock sets the real origin from the probed machine coordinates after all corners are done.\n"
    "  G10 L2 P1 X0 Y0 Z0\n"
    "\n"
    "  ; --- direction signs from the corner id ---\n"
    "  o10 IF [[#<corner> EQ 1] OR [#<corner> EQ 3]]\n"
    "    #<sx> = 1\n"
    "  o10 ELSE\n"
    "    #<sx> = -1\n"
    "  o10 ENDIF\n"
    "  o11 IF [[#<corner> EQ 1] OR [#<corner> EQ 2]]\n"
    "    #<sy> = 1\n"
    "  o11 ELSE\n"
    "    #<sy> = -1\n"
    "  o11 ENDIF\n"
    "  (PRINT, PC ENTER corner=#<corner> sx=#<sx> sy=#<sy> rad=#<rad> rx=#<rx> ry=#<ry> startz=#<sz_in>)\n"
    "\n"
    "  ; ================= spoilboard reference Z (first corner / DISCOVER only, 3D probe only) =================\n"
    "  ; Probed once at the origin reference (clear air below per preconditions) to anchor thickness;\n"
    "  ; later corners skip it. Only used to guard very thin stock when picking start_z.\n"
    "  o20 IF [[#<sz_in> GE 9000] AND [#<mode> EQ 0]]\n"
    "    G90\n"
    "    G53 G0 Z0                                     ; rapid - Z0 is the machine top, always clear\n"
    "    G53 G0 X[#<rx> + [#<_ls_spoilx> * #<sx>]] Y[#<ry> + [#<_ls_spoily> * #<sy>]]   ; rapid - travelling AT Z0\n"
    "    G53 G1 F1000 Z[#<_ls_spoilz>]          ; controlled - descending toward the (unverified) spoilboard\n"
    "    ; SAFETY: bound the spoilboard probe to a SHORT reach below the start Z. If the probe fails to trip\n"
    "    ; (mis-wired, wrong $6 polarity, not seated, on the wrong input) a G38.2 to a deep machine target drives\n"
    "    ; straight into - through - the spoilboard before alarming. Capping the seek to ~12 mm below the start\n"
    "    ; means a dead probe alarms after a few mm instead. So the fixture instance must be captured within ~10 mm\n"
    "    ; above the spoilboard. G54 was zeroed above, so work Z == machine Z here and #<_ls_spoilz> is the datum.\n"
    "    G38.2 Z[#<_ls_spoilz> - 12] F[#<_ls_searchf>] ; slow probe to the spoilboard, capped 12 mm below the start Z\n"
    "    G91 G1 Z2 F1000\n"
    "    G38.2 Z-5 F[#<_ls_latchf>]\n"
    "    #<_z_spoil> = #5063\n"
    "    G91 G1 Z10 F1000\n"
    "    G90\n"
    "    (PRINT, PC z_spoil=#<_z_spoil>)\n"
    "    ; Effective floor for the face-probe start height = spoilboard + sacrificial spacer/backer thickness\n"
    "    ; (#<_ls_spacer>, 0 when none). With a backer under the stock the real material is only the band ABOVE\n"
    "    ; it, so start_z must land in that band - not down in the backer/tape. Persists as a global for REUSE corners.\n"
    "    #<_bottom> = [#<_z_spoil> + #<_ls_spacer>]\n"
    "    (PRINT, PC bottom=#<_bottom> spacer=#<_ls_spacer>)\n"
    "  o20 ENDIF\n"
    "\n"
    "  ; ================= placeholder floor (first corner / DISCOVER only, touch plate only) =================\n"
    "  ; A continuity probe never falsely triggers on non-conductive spoilboard, so there is nothing to discover\n"
    "  ; there - skip the probe entirely. #<_bottom> just needs SOME value before the approach-height/seek-cap\n"
    "  ; math below runs; it is overwritten with a REAL value, anchored to this corner's own measured stock top,\n"
    "  ; right after that probe completes (see the block below it).\n"
    "  o21 IF [[#<sz_in> GE 9000] AND [#<mode> EQ 1]]\n"
    "    #<_bottom> = [#<_ls_spoilz> - 20]\n"
    "    (PRINT, PC bottom=#<_bottom> [touch plate placeholder])\n"
    "  o21 ENDIF\n"
    "\n"
    "  ; ================= stock-top Z at THIS corner (EVERY corner -> flatness) =================\n"
    "  ; Move the fixture type's top-probe offset (#<_ls_topx>/#<_ls_topy>) into the stock interior (sign per\n"
    "  ; corner) and probe the top, so each corner reports its own Z - the spread across the four corners is\n"
    "  ; the stock/spoilboard flatness. #<_topx>/#<_topy> persist as the edge probes' anchor below.\n"
    "  G90\n"
    "  o40 IF [#<sz_in> GE 9000]\n"
    "    G53 G0 Z[#<_bottom> + 30]        ; rapid - first corner: assume material <= 1in (25.4mm) ABOVE the floor (spoilboard+spacer), a COMPUTED safe clearance (floor known from the DISCOVER probe above), travel just above the tallest possible top\n"
    "  o40 ELSE\n"
    "    o42 IF [#<maxz> GT 0]\n"
    "      G53 G0 Z[#<maxz>]             ; rapid - caller already knows a trusted safe height (e.g. the vise's own centre probe) - never go any higher than necessary\n"
    "    o42 ELSE\n"
    "      G53 G0 Z0                     ; rapid - later corners: retract FULLY to machine top before crossing to the next corner - safer than just above the previous corner's stock in case there's clamp/fence hardware in between\n"
    "    o42 ENDIF\n"
    "  o40 ENDIF\n"
    "  #<_topx> = [#<rx> + [#<_ls_topx> * #<sx>]]\n"
    "  #<_topy> = [#<ry> + [#<_ls_topy> * #<sy>]]\n"
    "  G53 G0 X[#<_topx>] Y[#<_topy>]    ; rapid - travelling AT the safe height set above\n"
    "  o41 IF [#<sz_in> LT 9000]\n"
    "    ; Descend to a safe height before this corner's own top probe - NOT #<_safe_z>, which still holds the\n"
    "    ; PREVIOUS corner's height (top+20) at this point in the code (this corner's own top probe, which\n"
    "    ; recomputes it, hasn't run yet). Flatness/spacer variance between corners means the previous corner's\n"
    "    ; safe height can sit below THIS corner's actual top - a bare G0 rapid to a stale height would drive\n"
    "    ; straight into solid stock with nothing to catch it. If the caller already knows a trusted height\n"
    "    ; (#<maxz>, e.g. the vise's own centre probe) use that directly; otherwise fall back to the same\n"
    "    ; conservative floor+30 estimate the DISCOVER corner uses above (same reasoning as o40 above).\n"
    "    o43 IF [#<maxz> GT 0]\n"
    "      G53 G0 Z[#<maxz>]\n"
    "    o43 ELSE\n"
    "      G53 G0 Z[#<_bottom> + 30]\n"
    "    o43 ENDIF\n"
    "  o41 ENDIF\n"
    "  ; SAFETY + early-out. The stock top always sits ABOVE the effective floor (spoilboard + spacer), so bound\n"
    "  ; this seek instead of driving to a deep machine target - a dead/mis-wired probe then alarms near the board\n"
    "  ; instead of ploughing to -140. DISCOVER (corner 1, reliably over stock) seeks to just below the spoilboard.\n"
    "  ; REUSE corners are placed from the ESTIMATED size, so cap them at the floor: a real corner triggers on the\n"
    "  ; material above it, but a corner left over BARE board (estimate too big) reaches the floor with nothing\n"
    "  ; there and G38.2 aborts right away - no doomed side search into air. The spacer band guarantees the cap\n"
    "  ; clears the board (floor > spoilboard); with spacer 0 the +1 keeps it a hair above the board.\n"
    "  o45 IF [#<sz_in> GE 9000]\n"
    "    o46 IF [#<mode> EQ 0]\n"
    "      G38.2 Z[#<_z_spoil> - 2] F[#<_ls_searchf>]      ; DISCOVER, 3D probe: seek to just below the spoilboard\n"
    "    o46 ELSE\n"
    "      G38.2 Z[#<_ls_spoilz> - 12] F[#<_ls_searchf>]   ; DISCOVER, touch plate: seek to just below the fixture's saved reference (no spoilboard probe was run)\n"
    "    o46 ENDIF\n"
    "  o45 ELSE\n"
    "    G38.2 Z[#<_bottom> + 1] F[#<_ls_searchf>]        ; REUSE: refuse to seek below the material floor\n"
    "  o45 ENDIF\n"
    "  G91 G1 Z2 F1000\n"
    "  G38.2 Z-5 F[#<_ls_latchf>]\n"
    "  #<_z_top> = #5063\n"
    "  #<_safe_z> = [#<_z_top> + 20]     ; safe travel height now known: 20 mm above this corner's top\n"
    "  G91 G1 Z10 F1000\n"
    "  G90\n"
    "  (PRINT, PC z_top=#<_z_top>)\n"
    "  ; Touch plate DISCOVER: replace the placeholder floor with a REAL one, anchored to this corner's own\n"
    "  ; just-measured top (30 mm margin for stock-flatness variance) - REUSE corners below read this same\n"
    "  ; global, same as the 3D-probe path's spoilboard-anchored #<_bottom>.\n"
    "  o22 IF [[#<sz_in> GE 9000] AND [#<mode> EQ 1]]\n"
    "    #<_bottom> = [#<_z_top> - 30]\n"
    "    (PRINT, PC bottom=#<_bottom> [touch plate, from measured top])\n"
    "  o22 ENDIF\n"
    "\n"
    "  ; ================= start_z for the face probes (centre tip at the material's MIDPOINT) =================\n"
    "  ; top - thickness/2 always lands inside the material regardless of thickness (unlike a fixed offset below\n"
    "  ; the top, which could miss thin stock or catch a top chamfer/rounded edge on thick stock) - self-safe by\n"
    "  ; construction, so no #<_bottom>-based thin-stock fallback is needed here anymore.\n"
    "  #<_start_z> = [#<_z_top> - [#<_ls_thickness> / 2]]\n"
    "  ; SAFETY: never position the probe below the machine's Z soft-limit floor (#<_ls_zfloor>, passed by Load Stock\n"
    "  ; from $132). When the stock sits low - its top near the Z travel bottom - start_z can fall below\n"
    "  ; reachable Z, and the G53 G1 descent to it trips Alarm:2 (soft limit). Clamp up to the floor; the side face is\n"
    "  ; still contacted since the face seek is horizontal from start_z.\n"
    "  o32 IF [#<_start_z> LT #<_ls_zfloor>]\n"
    "    #<_start_z> = #<_ls_zfloor>\n"
    "  o32 ENDIF\n"
    "  (PRINT, PC start_z=#<_start_z>)\n"
    "\n"
    "  ; ================= X face probe =================\n"
    "  ; From the top-probe position (over solid stock, verified above) move ONLY X back out to the reference\n"
    "  ; (the face) - Y unchanged, so the pre-seek position is anchored to a point already known to be over\n"
    "  ; material rather than a separately estimated offset. Descend to start_z, then seek toward the face.\n"
    "  G53 G0 Z[#<_safe_z>]              ; rapid - retract only to just above the stock top (top + 20, VERIFIED by the probe just run), not machine top\n"
    "  G53 G0 X[#<rx>] Y[#<_topy>]       ; rapid - travelling AT the verified safe height\n"
    "  G53 G0 Z[#<_z_top> + 12]          ; rapid down to within 12mm of the KNOWN top (just probed) - controlled feed only takes over for the final approach\n"
    "  G53 G1 F1000 Z[#<_start_z>]       ; controlled - final descent to the face-probe depth\n"
    "  ; ABSOLUTE seeks (not G91): a G91 move right after a G53 mis-computes on a $23-inverted axis\n"
    "  ; (firmware bug - target sign-flips -> false Alarm:2). Current X is #<rx>, so seek to an absolute X.\n"
    "  G38.2 X[#<rx> + [35 * #<sx>]] F[#<_ls_searchf>]      ; coarse seek toward the X face\n"
    "  #<x_c1> = #5061\n"
    "  G1 X[#<x_c1> - [4 * #<sx>]] F1000                    ; back off so the deflecting ball RELEASES before the slow re-probe (G1: gentle, no rapid-accel jerk)\n"
    "  G38.2 X[#<x_c1> + [6 * #<sx>]] F[#<_ls_latchf>]      ; slow re-probe (2 mm back-off left it stuck triggered -> Alarm:4; 4 mm clears it)\n"
    "  #<x_trig> = #5061\n"
    "  G1 X[#<x_trig> - [10 * #<sx>]] F1000\n"
    "  G90\n"
    "  (PRINT, PC x_trig=#<x_trig>)\n"
    "\n"
    "  ; ================= Y face probe (route axis-at-a-time around the corner) =================\n"
    "  ; Retract to safe Z first - the X face probe left the tip near start_z (probing depth), and the top-probe\n"
    "  ; XY is over solid stock, so crossing there at probing depth would drag the tip across the stock top.\n"
    "  ; Back to the top-probe XY, STILL AT SAFE HEIGHT move ONLY Y out to the reference (clear air outside the\n"
    "  ; Y face) - X unchanged. Only THEN descend to start_z: (topx, ry) is clear of stock (Y outside the face),\n"
    "  ; whereas (topx, topy) is the exact point the top probe just touched - descending there would hit stock.\n"
    "  G53 G0 Z[#<_safe_z>]              ; rapid - verified-safe height (see X face above)\n"
    "  G53 G0 X[#<_topx>] Y[#<_topy>]    ; rapid - travelling AT that height\n"
    "  G53 G0 Y[#<ry>]                   ; rapid - still AT that height\n"
    "  G53 G0 Z[#<_z_top> + 12]          ; rapid down to within 12mm of the KNOWN top (see X face above)\n"
    "  G53 G1 F1000 Z[#<_start_z>]       ; controlled - final descent to the face-probe depth\n"
    "  ; ABSOLUTE seeks (see X face) - current Y is #<ry>, so seek to an absolute Y.\n"
    "  G38.2 Y[#<ry> + [35 * #<sy>]] F[#<_ls_searchf>]      ; coarse seek toward the Y face\n"
    "  #<y_c1> = #5062\n"
    "  G1 Y[#<y_c1> - [4 * #<sy>]] F1000                    ; back off before the slow re-probe (G1: gentle, no rapid-accel jerk)\n"
    "  G38.2 Y[#<y_c1> + [6 * #<sy>]] F[#<_ls_latchf>]      ; slow re-probe\n"
    "  #<y_trig> = #5062\n"
    "  G1 Y[#<y_trig> - [10 * #<sy>]] F1000\n"
    "  G90\n"
    "  (PRINT, PC y_trig=#<y_trig>)\n"
    "\n"
    "  ; ================= outputs (radius compensated) =================\n"
    "  #<_corner_x> = [#<x_trig> + [#<rad> * #<sx>]]\n"
    "  #<_corner_y> = [#<y_trig> + [#<rad> * #<sy>]]\n"
    "  #<_corner_z> = [#<_z_top> - #<_ls_plateoffset>]   ; 0 for the 3D probe and touch-plate-on-conductive-stock (no-op)\n"
    "  (PRINT, PC OUT c=#<corner> x=#<_corner_x> y=#<_corner_y> z=#<_corner_z>)\n"
    "\n"
    "  ; retract to just above the stock top - the next corner travels at this height. Rapid: _safe_z is a\n"
    "  ; VERIFIED height (20mm above this corner's just-probed top), so this retract only ever moves AWAY from\n"
    "  ; material, never toward it.\n"
    "  G53 G0 Z[#<_safe_z>]\n"
    "  (PRINT, PC EXIT)\n"
    "O<pcorner> ENDSUB\n"
    "\n";

static const char *embedded_macro_pvisecorner =
    "; pvisecorner.macro - probes a machinist vise's FIXED JAW front-left corner for grblHAL.\n"
    ";\n"
    "; Unlike pcorner.macro (which needs its reference OUTSIDE both faces, over open spoilboard), this macro's\n"
    "; reference sits OVER the jaw interior, near the corner - the FixtureEditDialog schematic's clearance circle\n"
    "; is centered there, with the corner on its boundary. That's the opposite geometry, so this is its own macro\n"
    "; rather than a variant of pcorner: probe the jaw top DIRECTLY at the reference (no separate spoilboard probe -\n"
    "; the jaw is rigid and bolted down, so its own top is the only surface that matters), then for each face back\n"
    "; OFF outward (away from the jaw interior) to clear air, descend, and seek back INWARD to find it - the mirror\n"
    "; image of pcorner's outside-in approach.\n"
    ";\n"
    "; Args via GLOBALS set before a NO-ARG call (grblHAL's O-word CALL does not reliably accept multiple bracketed\n"
    "; args), then invoke:\n"
    ";   #<_lv_refx>, #<_lv_refy>, #<_lv_refz> = machine position jogged over the jaw, near its front-left corner,\n"
    ";                   within the schematic's clearance circle AND within ~10 mm above the jaw top.\n"
    ";   #<_lv_rad>    = probe tip radius (mm).\n"
    ";   #<_lv_clear>  = distance (mm) to back off OUTWARD (away from the jaw) from the reference before each face\n"
    ";                   seek - must clear the probe body off the corner, same idea as pcorner's topx/topy offset.\n"
    ";   #<_lv_searchf>= fast search feed (mm/min), from the 3D probe definition (Probe/Search feed).\n"
    ";   #<_lv_latchf> = slow latch / re-probe feed (mm/min), from the 3D probe definition (Latch feed).\n"
    ";   #<_lv_zfloor> = machine Z soft-limit floor (machine coords) - never position the probe below this.\n"
    ";\n"
    "; Outputs (GLOBAL named params, survive the SUB):\n"
    ";   #<_corner_x> #<_corner_y>   radius-compensated jaw corner XY (machine coords)\n"
    ";   #<_corner_z>                the jaw's top Z (machine) at the reference\n"
    ";\n"
    "; Preconditions: homed; probe on the main probe input ($6 polarity correct); the reference must be within\n"
    "; ~10 mm above the jaw top (the top-probe search is capped 12 mm below it) and clear of both faces by less\n"
    "; than #<_lv_clear> (so backing off #<_lv_clear> outward truly reaches open air beside the jaw).\n"
    "\n"
    "O<pvisecorner> SUB\n"
    "  #<rad> = #1                    ; tip radius = the single CALL arg; rest via globals\n"
    "  #<rx>  = #<_lv_refx>\n"
    "  #<ry>  = #<_lv_refy>\n"
    "  #<rz>  = #<_lv_refz>\n"
    "\n"
    "  ; Clear G54 so the absolute Z probes below run in machine coordinates (same reasoning as pcorner.macro).\n"
    "  G10 L2 P1 X0 Y0 Z0\n"
    "  G90\n"
    "  (PRINT, PV ENTER rx=#<rx> ry=#<ry> rz=#<rz> rad=#<rad> clear=#<_lv_clear>)\n"
    "\n"
    "  ; ================= jaw top Z, probed directly at the reference (already over the jaw) =================\n"
    "  G53 G0 Z0                    ; rapid - Z0 is the machine top, always clear\n"
    "  G53 G0 X[#<rx>] Y[#<ry>]     ; rapid - travelling AT Z0\n"
    "  G53 G1 F1000 Z[#<rz>]        ; controlled - descending toward the (unverified) jogged reference, near the jaw\n"
    "  ; SAFETY: cap the search 12 mm below the reference, same reasoning as pcorner.macro's spoilboard/top probes -\n"
    "  ; a dead/mis-wired probe alarms near the jaw instead of ploughing on.\n"
    "  G38.2 Z[#<rz> - 12] F[#<_lv_searchf>]\n"
    "  G91 G1 Z2 F1000\n"
    "  G38.2 Z-5 F[#<_lv_latchf>]\n"
    "  #<_top_z> = #5063\n"
    "  G91 G1 Z10 F1000\n"
    "  G90\n"
    "  (PRINT, PV top_z=#<_top_z>)\n"
    "  #<_safe_z>  = [#<_top_z> + 20]   ; safe travel height: 20 mm above the jaw top\n"
    "  #<_start_z> = [#<_top_z> - 4]    ; face-seek height: centre tip 4 mm below the jaw top\n"
    "  o10 IF [#<_start_z> LT #<_lv_zfloor>]\n"
    "    #<_start_z> = #<_lv_zfloor>\n"
    "  o10 ENDIF\n"
    "  (PRINT, PV start_z=#<_start_z>)\n"
    "\n"
    "  ; ================= X face (jaw's left end) =================\n"
    "  ; Back off OUTWARD (left, -X) from the reference by #<_lv_clear> - clear of the jaw - then descend and seek\n"
    "  ; back INWARD (+X) to find the face. Mirror image of pcorner's X-face section.\n"
    "  G53 G0 Z[#<_safe_z>]                            ; rapid - VERIFIED height, just probed\n"
    "  G53 G0 X[#<rx> - #<_lv_clear>] Y[#<ry>]         ; rapid - travelling AT that height\n"
    "  G53 G0 Z[#<_top_z> + 12]                        ; rapid down to within 12mm of the KNOWN top (just probed) - controlled feed only takes over for the final approach\n"
    "  G53 G1 F1000 Z[#<_start_z>]                     ; controlled - final descent to the face-probe depth\n"
    "  G38.2 X[#<rx> + 20] F[#<_lv_searchf>]           ; coarse seek back toward/past the reference\n"
    "  #<x_c1> = #5061\n"
    "  G1 X[#<x_c1> - 4] F1000                         ; back off so the deflecting ball releases before the slow re-probe\n"
    "  G38.2 X[#<x_c1> + 6] F[#<_lv_latchf>]           ; slow re-probe\n"
    "  #<x_trig> = #5061\n"
    "  G1 X[#<x_trig> - 10] F1000\n"
    "  G90\n"
    "  (PRINT, PV x_trig=#<x_trig>)\n"
    "\n"
    "  ; ================= Y face (jaw's clamping face, front) =================\n"
    "  ; Retract to safe Z before crossing back over the jaw (same reasoning as pcorner: never traverse at probing\n"
    "  ; depth over solid material). Back off OUTWARD (front, -Y) by #<_lv_clear>, descend, seek back INWARD (+Y).\n"
    "  G53 G0 Z[#<_safe_z>]                            ; rapid - VERIFIED height (see X face above)\n"
    "  G53 G0 X[#<rx>] Y[#<ry> - #<_lv_clear>]         ; rapid - travelling AT that height\n"
    "  G53 G0 Z[#<_top_z> + 12]                        ; rapid down to within 12mm of the KNOWN top (see X face above)\n"
    "  G53 G1 F1000 Z[#<_start_z>]                     ; controlled - final descent to the face-probe depth\n"
    "  G38.2 Y[#<ry> + 20] F[#<_lv_searchf>]\n"
    "  #<y_c1> = #5062\n"
    "  G1 Y[#<y_c1> - 4] F1000\n"
    "  G38.2 Y[#<y_c1> + 6] F[#<_lv_latchf>]\n"
    "  #<y_trig> = #5062\n"
    "  G1 Y[#<y_trig> - 10] F1000\n"
    "  G90\n"
    "  (PRINT, PV y_trig=#<y_trig>)\n"
    "\n"
    "  ; ================= outputs (radius compensated) =================\n"
    "  #<_corner_x> = [#<x_trig> + #<rad>]\n"
    "  #<_corner_y> = [#<y_trig> + #<rad>]\n"
    "  #<_corner_z> = #<_top_z>\n"
    "  (PRINT, PV OUT x=#<_corner_x> y=#<_corner_y> z=#<_corner_z>)\n"
    "\n"
    "  ; retract to just above the jaw top - rapid: _safe_z is VERIFIED (20mm above the just-probed top), so this\n"
    "  ; only ever moves AWAY from the jaw, never toward it.\n"
    "  G53 G0 Z[#<_safe_z>]\n"
    "  (PRINT, PV EXIT)\n"
    "O<pvisecorner> ENDSUB\n"
    "\n";

#endif // EMBEDDED_MACROS_H
